using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json.Linq;
namespace IslandGame.Editor {
 public static class SourceEnvironmentImport {
  const string Root="Assets/Island/SourceEnvironment/",Native="Assets/GenshinOriginal/Lods/";
  static Dictionary<string,Material> mats=new Dictionary<string,Material>();
  static T Save<T>(T obj,string path) where T:UnityEngine.Object {var old=AssetDatabase.LoadAssetAtPath<T>(path);if(old){EditorUtility.CopySerialized(obj,old);UnityEngine.Object.DestroyImmediate(obj);return old;}AssetDatabase.CreateAsset(obj,path);return obj;}
  static Texture2D Texture(string name){string path=Root+"Art/"+name+".png";if(!File.Exists(path)&&File.Exists(Native+name+".png"))AssetDatabase.CopyAsset(Native+name+".png",path);return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
  static Material Material(string name){if(mats.TryGetValue(name,out var known))return known;string path=Native+name+".material.json";bool leaf=name.Contains("Leaf");var m=new Material(Shader.Find(leaf?"Island/Source/Leaf":"Universal Render Pipeline/Lit")){name=name,enableInstancing=true};
   if(File.Exists(path)){var j=JObject.Parse(File.ReadAllText(path));foreach(var v in (JObject)j["properties"]["m_Floats"])if(m.HasProperty(v.Key))m.SetFloat(v.Key,(float)v.Value);foreach(var v in (JObject)j["properties"]["m_Colors"]){var c=v.Value;if(m.HasProperty(v.Key))m.SetColor(v.Key,new Color((float)c["r"],(float)c["g"],(float)c["b"],(float)c["a"]));}
    foreach(var t in (JArray)j["textures"]){string prop=(string)t["property"];if(prop!="_MainTex"&&prop!="_BumpMap")continue;var tex=Texture((string)t["name"]);if(!tex)continue;string dest=leaf?prop:prop=="_MainTex"?"_BaseMap":"_BumpMap";if(m.HasProperty(dest)){m.SetTexture(dest,tex);if(prop=="_BumpMap")m.EnableKeyword("_NORMALMAP");}}
   }
   if(!leaf){m.SetFloat("_Smoothness",.12f);m.SetFloat("_Metallic",0);m.SetColor("_BaseColor",Color.white);}m=Save(m,Root+"Art/"+name+".mat");mats[name]=m;return m;
  }
  static GameObject Prop(string stem){var root=new GameObject(stem);var lods=new List<LOD>();for(int level=0;level<2;level++){string path=Native+stem+"_Lod"+level+".fbx";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab)continue;var model=UnityEngine.Object.Instantiate(prefab,root.transform,false);model.name="LOD"+level;foreach(var f in model.GetComponentsInChildren<MeshFilter>()){var copy=UnityEngine.Object.Instantiate(f.sharedMesh);copy.name=f.sharedMesh.name;f.sharedMesh=Save(copy,Root+"Art/"+stem+"_"+level+"_"+f.name+".asset");}foreach(var r in model.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>Material(m.name)).ToArray();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;r.receiveShadows=true;}lods.Add(new LOD(level==0?.18f:.012f,model.GetComponentsInChildren<Renderer>()));}
   var group=root.AddComponent<LODGroup>();group.SetLODs(lods.ToArray());group.RecalculateBounds();var saved=PrefabUtility.SaveAsPrefabAsset(root,Root+"Art/"+stem+".prefab");UnityEngine.Object.DestroyImmediate(root);return saved;
  }
  public static string BakeCoverage(){
   if(EditorApplication.isPlaying)throw new Exception("Stop before baking");var rows=JArray.Parse(File.ReadAllText("G:/holdem_coin-workspace/island-genshin-localcombat-20261110/repository/src/lib/generated/mount-sunday-zones.json"));var counts=new List<int>();
   for(int zone=0;zone<10;zone++){var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Island/MountRuntime/Scenes/MountZone"+(zone+1).ToString("00")+".unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);try{var env=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MountZoneEnvironment>(true)).First();env.gameObject.SetActive(true);var ground=env.GetComponentsInChildren<MeshCollider>(true).Where(c=>c.name.StartsWith("Terrain_")||c.name.StartsWith("Playable ground")).ToArray();var colors=ground.ToDictionary(c=>c,c=>c.sharedMesh.colors);var triangles=ground.ToDictionary(c=>c,c=>c.sharedMesh.triangles);Physics.SyncTransforms();var row=rows[zone];var path=(JArray)row["path"];float minX=(float)row["minX"]/100-18,maxX=(float)row["maxX"]/100+18,minZ=path.Min(v=>(float)v["z"])-25,maxZ=path.Max(v=>(float)v["z"])+25;var points=new List<Vector3>();var rng=new System.Random(111+zone);
    for(float x=minX;x<maxX;x+=.38f)for(float z=minZ;z<maxZ;z+=.38f){float px=x+(float)rng.NextDouble()*.3f,pz=z+(float)rng.NextDouble()*.3f;var ray=new Ray(new Vector3(px,80,pz),Vector3.down);float distance=float.MaxValue;RaycastHit hit=default;foreach(var c in ground)if(c.Raycast(ray,out var candidate,160)&&candidate.distance<distance){hit=candidate;distance=hit.distance;}if(distance==float.MaxValue||hit.normal.y<.72f)continue;var mc=(MeshCollider)hit.collider;var cc=colors[mc];var tt=triangles[mc];int index=hit.triangleIndex*3;if(cc.Length>0&&index+2<tt.Length){var weights=hit.barycentricCoordinate;float road=cc[tt[index]].a*weights.x+cc[tt[index+1]].a*weights.y+cc[tt[index+2]].a*weights.z;if(road>.65f||road>.25f&&rng.NextDouble()<road)continue;}points.Add(hit.point+Vector3.up*.006f);}if(points.Count==0)throw new Exception("No ground coverage for zone "+zone);WritePoints(Root+"Positions/Zone"+zone.ToString("00")+".bytes",points);counts.Add(points.Count);
   }finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}}
   var prefab=Resources.Load<GameObject>("NatureAuthoredMap");var terrain=prefab.GetComponentInChildren<Terrain>(true);var td=terrain.terrainData;var pos=terrain.transform.position;var boss=new List<Vector3>();var random=new System.Random(211);for(float x=10;x<100;x+=.42f)for(float z=-44;z<62;z+=.42f){float px=x+(float)random.NextDouble()*.32f,pz=z+(float)random.NextDouble()*.32f,u=(px-pos.x)/td.size.x,v=(pz-pos.z)/td.size.z;if(u<0||v<0||u>1||v>1||td.GetInterpolatedNormal(u,v).y<.72f)continue;boss.Add(new Vector3(px,pos.y+td.GetInterpolatedHeight(u,v)+.006f,pz));}WritePoints(Root+"Positions/Boss.bytes",boss);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var assets=Resources.Load<SourceEnvironmentAssets>("SourceEnvironmentAssets");assets.bossGrass=AssetDatabase.LoadAssetAtPath<TextAsset>(Root+"Positions/Boss.bytes");EditorUtility.SetDirty(assets);AssetDatabase.SaveAssets();string report=Newtonsoft.Json.JsonConvert.SerializeObject(new{zones=counts,boss=boss.Count,spacing=.38});File.WriteAllText("G:/holdem_coin-workspace/island-genshin-localcombat-20261110/evidence/expanded-grass.json",report);return report;
  }
  static void WritePoints(string path,List<Vector3> points){using(var w=new BinaryWriter(File.Create(path))){w.Write(points.Count);foreach(var p in points){w.Write(p.x);w.Write(p.y);w.Write(p.z);}}}
  public static string Apply(){if(EditorApplication.isPlaying||BuildPipeline.isBuildingPlayer)throw new Exception("Stop before importing");Directory.CreateDirectory(Root+"Art");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);mats.Clear();var a=ScriptableObject.CreateInstance<SourceEnvironmentAssets>();a.grassLods=new Mesh[4];for(int i=0;i<4;i++){var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/GenshinOriginal/Grass/Area_Common_Flower_LongGras_01_Lod"+i+".asset");a.grassLods[i]=Save(UnityEngine.Object.Instantiate(source),Root+"Art/GrassLOD"+i+".asset");}
   var grass=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/GenshinOriginal/Grass/Area_Common_Flower_Gras_01_0.mat"));grass.shader=Shader.Find("Island/Source/Grass");grass.enableInstancing=true;grass.SetTexture("_Noisemap",Texture("Stages_Vegetation_T4_Noise_NoStream"));a.grassMaterial=Save(grass,Root+"Art/Grass.mat");a.zones=Enumerable.Range(0,10).Select(i=>AssetDatabase.LoadAssetAtPath<TextAsset>(Root+"Positions/Zone"+i.ToString("00")+".bytes")).ToArray();a.bossGrass=AssetDatabase.LoadAssetAtPath<TextAsset>(Root+"Positions/Boss.bytes");a.trees=new[]{Prop("Stages_CyTree01"),Prop("Stages_FirTree01")};a.rocks=new[]{Prop("Stages_MDSRock06"),Prop("Stages_MDSRock07")};Save(a,"Assets/Island/Resources/SourceEnvironmentAssets.asset");AssetDatabase.SaveAssets();return "Created source grass, 2 trees, 2 rocks with LOD and shadows";
  }
 }
}
